package io.knowledgebrain.learning;
import io.knowledgebrain.contracts.learning.courseprogressshare.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class CourseProgressShareKafkaIntegrationTest {
 @Test void enrollmentCdcBytesAndUnacknowledgedReplay()throws Exception{
  var test=new CourseProgressShareStoreIntegrationTest();test.setup();var f=test.f;f.change(0,0,"COMPLETED");var v=test.share(0,1);f.change(1,1,"COMPLETED");test.share(1,2);test.store.change(test.a,2,"WITHDRAWN",0,f.trace);var expected=new HashMap<String,byte[]>();for(var bytes:f.sql.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.shareId())){var e=CourseProgressShareEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(3,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP"));options.put("group.id","learning-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/learning-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/learning-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/learning-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("learning.course-progress-share.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<3&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=CourseProgressShareEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(e.getAggregateId(),record.key());assertEquals(f.trace,e.getTraceId());assertEquals(f.ref.spaceId().toString(),e.getSpaceId());assertEquals("CourseProgressShare",e.getAggregateType());var p=CourseProgressShareSnapshotV1.parseFrom(e.getPayload());assertEquals(v.shareId().toString(),p.getShareId());assertEquals(f.ref.principalId().toString(),p.getParticipantId());assertEquals("OWNER",p.getAudience());assertEquals(3,p.getCourseVersion());for(var entry:Map.of("trace_id",f.trace,"schema_group","learning","schema_artifact","course-progress-share-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS learning.course-progress-share.v1 three byte-exact Course progress snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
